-- 요청 문맥이 있는 연결은 DB에서도 개인 자료만 읽고 쓴다.
ALTER TABLE magi_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_jobs FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_jobs USING (current_setting('magi.internal',true)='on' OR owner_id=current_setting('magi.actor',true)) WITH CHECK (current_setting('magi.internal',true)='on' OR owner_id=current_setting('magi.actor',true));
ALTER TABLE magi_executions ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_executions FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_executions USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id));
ALTER TABLE magi_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_snapshots FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_snapshots USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id));
ALTER TABLE magi_artifacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_artifacts FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_artifacts USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id));
ALTER TABLE magi_nodes ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_nodes FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_nodes USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_jobs j WHERE j.id=job_id));
ALTER TABLE magi_edges ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_edges FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_edges USING (current_setting('magi.internal',true)='on' OR (EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=source) AND EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=target))) WITH CHECK (current_setting('magi.internal',true)='on' OR (EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=source) AND EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=target)));
ALTER TABLE magi_chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_chunks FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_chunks USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id));
ALTER TABLE magi_chunk_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_chunk_sets FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_chunk_sets USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id));
ALTER TABLE magi_chunk_vectors ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_chunk_vectors FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_chunk_vectors USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_chunks c WHERE c.id=chunk_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_chunks c WHERE c.id=chunk_id));
ALTER TABLE magi_embeddings ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_embeddings FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_embeddings USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id));
ALTER TABLE magi_embedding_queue ENABLE ROW LEVEL SECURITY;
ALTER TABLE magi_embedding_queue FORCE ROW LEVEL SECURITY;
CREATE POLICY magi_owner ON magi_embedding_queue USING (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id)) WITH CHECK (current_setting('magi.internal',true)='on' OR EXISTS(SELECT 1 FROM magi_nodes n WHERE n.id=node_id));
